                          Status="In Progress"
                          Tasks="InProgressTasks"
                          ShowMoveLeft="true"
                          ShowMoveRight="true"
                          OnMoveLeft="MoveToTodo"
                          OnMoveRight="MoveToDone"
                          OnAddTask="HandleAddTask" />

            <KanbanColumn ColumnName="Done"
                          Status="Done"
                          Tasks="DoneTasks"
                          ShowMoveLeft="true"
                          ShowMoveRight="false"
                          OnMoveLeft="MoveToInProgress"
                          OnAddTask="HandleAddTask" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
