@@ -1,0 +1,155 @@
+@page "/board"
+@using sv_c998684e8fb94af583ef2acac52c59e1.Services
+@inject ITaskService TaskService
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<div class="kanban-board">
+    @if (isLoading)
+    {
+        <div class="board-loading">Loading tasks...</div>
+    }
+    else if (errorMessage is not null)
+    {
+        <div class="board-error">
+            <p>@errorMessage</p>
+            <button @onclick="LoadTasks">Retry</button>
+        </div>
+    }
+    else
+    {
+        <BoardStats Total="@allTasks.Count"
+                    TodoCount="@TodoTasks.Count"
+                    InProgressCount="@InProgressTasks.Count"
+                    DoneCount="@DoneTasks.Count"
+                    OverdueCount="@OverdueCount" />
+
+        <BoardSearchBar SearchTerm="@searchTerm"
+                        SearchTermChanged="HandleSearchChanged" />
+
+        <div class="kanban-columns">
+            <KanbanColumn ColumnName="To Do"
+                          Status="To Do"
+                          Tasks="TodoTasks"
+                          ShowMoveLeft="false"
+                          ShowMoveRight="true"
+                          OnMoveRight="MoveToInProgress"
+                          OnAddTask="HandleAddTask" />
+
+            <KanbanColumn ColumnName="In Progress"
+                          Status="In Progress"
+                          Tasks="InProgressTasks"
+                          ShowMoveLeft="true"
+                          ShowMoveRight="true"
+                          OnMoveLeft="MoveToTodo"
+                          OnMoveRight="MoveToDone"
+                          OnAddTask="HandleAddTask" />
+
+            <KanbanColumn ColumnName="Done"
+                          Status="Done"
+                          Tasks="DoneTasks"
+                          ShowMoveLeft="true"
+                          ShowMoveRight="false"
+                          OnMoveLeft="MoveToInProgress"
+                          OnAddTask="HandleAddTask" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private string searchTerm = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchTerm)
+        ? allTasks
+        : allTasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
+
+    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
+    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchTerm = value;
+    }
+
+    private async Task MoveToTodo(TaskItem task)
+    {
+        await UpdateStatus(task, "To Do");
+    }
+
+    private async Task MoveToInProgress(TaskItem task)
+    {
+        await UpdateStatus(task, "In Progress");
+    }
+
+    private async Task MoveToDone(TaskItem task)
+    {
+        await UpdateStatus(task, "Done");
+    }
+
+    private async Task UpdateStatus(TaskItem task, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            var index = allTasks.FindIndex(t => t.Id == task.Id);
+            if (index >= 0)
+            {
+                allTasks[index] = task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private async Task HandleAddTask(AddTaskForm.NewTaskModel model)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
+            // The service creates with default status; update to match the column if needed
+            if (created.Status != model.Status)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, model.Status);
+                created = created with { Status = model.Status };
+            }
+            allTasks.Add(created);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
+

